export function getAuthenticFrameSvgInner(id: string): { scopedDefs: string; scopedBody: string } {
  const scopedDefs = RAW_DEFS_TEMPLATE
    .replace(/id="([^"]+)"/g, `id="$1_${id}"`)
    .replace(/url\(#([^)]+)\)/g, `url(#$1_${id})`);

  const scopedBody = RAW_BODY_TEMPLATE
    .replace(/id="([^"]+)"/g, `id="$1_${id}"`)
    .replace(/url\(#([^)]+)\)/g, `url(#$1_${id})`);

  return { scopedDefs, scopedBody };
}

export function getAuthenticFrameSvg(
  id: string,
  x0: number,
  yTop: number,
  width: number,
  height: number,
  _surahNumber?: number,
  _surahName?: string
): string {
  const { scopedDefs, scopedBody } = getAuthenticFrameSvgInner(id);
  const sx = (width / 240.20621).toFixed(6);
  const sy = (height / 30.23196).toFixed(6);

  return `
    <g id="${id}" class="surah_header_frame" overflow="visible" pointer-events="none" transform="translate(${x0.toFixed(2)}, ${yTop.toFixed(2)}) scale(${sx}, ${sy})">
      <defs>
        ${scopedDefs}
      </defs>
      ${scopedBody}
    </g>
  `;
}
